  const next = String(r.nextActionAt || '').slice(0, 10);
  if (!next || next > today) continue;
  if (amt <= 0) continue;
  const stage = String(r.stage || '');
  if (stage === 'drafted' || stage === 'queued') continue;
  if (istTodayTouch(r.lastTouchAt)) continue;
  due.push({ json: r });
